class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        self._limit_bytes = int(monthly_limit_mib * 1024 * 1024)
        self._usage = {}  # month -> dict[name -> size_bytes]

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        """month is a string like "2026-01"."""
        if size_bytes <= 0:
            raise ValueError("size_bytes must be positive")
        month_files = self._usage.setdefault(month, {})
        if name in month_files:
            return
        if self.used_bytes(month) + size_bytes > self._limit_bytes:
            raise ValueError("Monthly upload quota exceeded")
        month_files[name] = size_bytes

    def delete(self, name: str, month: str) -> None:
        month_files = self._usage.get(month)
        if month_files is not None:
            month_files.pop(name, None)

    def used_bytes(self, month: str) -> int:
        """How many bytes count towards the quota in the given month."""
        return sum(self._usage.get(month, {}).values())
